INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ظنن:khalil_kitab_ayn', 'ظنن', 'a1085f6aec2b4d8816f6404365', 'الظَّنينُ: المُعادي، والظَّنينُ: المُتَّهَمُ، والاسمْ الظِّنَّةُ', 'an enemy; a suspected man', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_35d3ee716a9569dd', '2922', NULL, 'blk_kay_e3d49dc91b542b48', 0, NULL, 'Marker: head gloss. Reading: suspicion. Differs from the main reading (guessing, doubt).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ظنن:ibn_durayd_jamharat_lugha', 'ظنن', 'a1085f6aec2b4d8816f6404365', 'الظَّن: مَعْرُوف ظن يظنّ ظنا والظنة: التُّهْمَة', 'thinking is well known; suspicion', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_78023e3388a2edba', '118', NULL, 'blk_jam_ce828ef9636beaee', 0, NULL, 'Marker: head gloss. Reading: suspicion. Differs from the main reading (guessing, doubt).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ظنن:jawhari_sihah', 'ظنن', 'a1085f6aec2b4d8816f6404365', 'الظن معروف، وقد يوضع موضع العلم', 'well known; sometimes used for knowing', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_570bb4162bb97a21', '4279', 6, 'blk_sih_9f96c03f3ff5f562', 0, NULL, 'Marker: head gloss. Reading: knowing. Differs from the main reading (guessing, doubt).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ظنن:raghib_mufradat', 'ظنن', 'a1085f6aec2b4d8816f6404365', 'الظَّنُّ: اسم لما يحصل عن أمارة، ومتى قويت أدّت إلى العلم، ومتى ضعفت جدّا لم يتجاوز حدّ التّوهّم', 'a view from signs: strong is knowing, weak is fancy', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_97b67931eed99bb3', '539', 1, 'blk_mfr_b7680ecd2c6e443d', 0, NULL, 'Marker: opening definition. Reading: judging from signs.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ظنن:ibn_manzur_lisan_arab', 'ظنن', 'a1085f6aec2b4d8816f6404365', 'الظَّنُّ شَكٌّ وَيَقِينٌ إِلَّا أَنه لَيْسَ بيقينِ عِيانٍ، إِنما هُوَ يقينُ تَدَبُّرٍ', 'doubt and certainty, but sure by thought, not sight', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_7a5958165bc02a8e', '6833', 13, 'blk_lsn_26e00685c81b005f', 0, NULL, 'Marker: head gloss. Reading: doubt and certainty. Quoted from Ibn Sīdah (al-Muḥkam) via Lisān.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ظنن:fayyumi_misbah_munir', 'ظنن', 'a1085f6aec2b4d8816f6404365', 'الظَّنُّ مَصْدَرٌ مِنْ بَابِ قَتَلَ وَهُوَ خِلَافُ الْيَقِينِ', 'the opposite of being sure', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_23517e3636133a64', '1953', NULL, 'blk_msb_968404a4431bc4f4', 0, NULL, 'Marker: head gloss. Reading: not being sure.', 'high', 'active');
