INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عتل:qamus_muhit', 'عتل', '63f1b05f2a49d90af8a7a20dc5', 'وعَتَلَهُ يَعْتِلُه ويَعْتُلُه فانْعَتَلَ: جَرَّهُ عَنيفاً فَحَمَلَهُ', 'he dragged him roughly and carried him off', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_df344ffeda61c355', NULL, NULL, 'blk_qms_cfc9fe44ebf34e4d', 0, NULL, 'Marker: verb gloss. Reading: rough dragging.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عتل:zabidi_taj_arus', 'عتل', '63f1b05f2a49d90af8a7a20dc5', 'قيلَ: هُوَ الْجَافِي الشَّدِيدُ، مِنَ الرِّجالِ والدَّوَابِّ', 'rough and hard, of men and beasts', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_eba7ea12f6bd6a54', '426', 29, 'blk_taj_366202c60ecc5148', 0, NULL, 'Marker: derived word gloss. Reading: harshness. Differs from the main reading (rough dragging).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:عتل:lane_lexicon', 'عتل', '63f1b05f2a49d90af8a7a20dc5', 'He drew him along, or dragged him, roughly, or violently', 'he dragged him roughly', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_16df33abc9e54593', '1948', NULL, 'blk_lane_dfb0b455180c2404', 0, NULL, 'Marker: first sense A1. Reading: rough dragging.', 'high', 'active');
UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: harshness, strength. Differs from the main reading (rough dragging).', updated_at = datetime('now') WHERE id = 'ASL:عتل:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
UPDATE ar_ling_root_asl SET is_primary = CASE WHEN id = 'ASL:عتل:ibn_durayd_jamharat_lugha' THEN 1 ELSE 0 END, updated_at = datetime('now') WHERE root_norm = 'عتل' AND EXISTS (SELECT 1 FROM ar_ling_root_asl WHERE id = 'ASL:عتل:ibn_durayd_jamharat_lugha' AND status <> 'rejected');
